"use strict";(self.webpackChunkdg_knowlege_base=self.webpackChunkdg_knowlege_base||[]).push([[9174],{18115:e=>{e.exports=JSON.parse('{"tag":{"label":"AI Agents","permalink":"/datagol-knowlegde-base-v1/docs/tags/ai-agents","allTagsPath":"/datagol-knowlegde-base-v1/docs/tags","count":14,"items":[{"id":"AI Agents/About AI agents","title":"About AI agents","description":"The DataGOL AI agents empowers business users and engineers to efficiently analyze and visualize data through a suite of specialized AI agents. These agents act as intelligent assistants, guiding users through the data exploration process and accelerating insights.","permalink":"/datagol-knowlegde-base-v1/docs/AI Agents/about-ai-agent"},{"id":"AI Agents/AI Search agent","title":"AI Search agent","description":"What is AI Search agent?","permalink":"/datagol-knowlegde-base-v1/docs/AI Agents/ai-search-agent"},{"id":"AI Agents/Business Intelligence (BI) agent - (Chart agent)","title":"Business Intelligence (BI) agent - (Chart agent)","description":"BI or Chart agent allows you to visualize data from structured datasets using various chart types and provides insights through graphical representations of data.","permalink":"/datagol-knowlegde-base-v1/docs/AI Agents/business-intelligence-BI-agent-Chart-agent"},{"id":"AI Agents/Custom agent","title":"Custom agent","description":"What is Custom agent?","permalink":"/datagol-knowlegde-base-v1/docs/AI Agents/custom-agent"},{"id":"AI Agents/Data Cleaning (DC) agent","title":"Data Cleaning (DC) agent","description":"The DC agent helps users to clean and organize their data within a workbook. This includes tasks like deduplication, normalization, data imputation, and filtering.","permalink":"/datagol-knowlegde-base-v1/docs/AI Agents/data-cleaning-agent-DCA-agent"},{"id":"AI Agents/Data Conversation agent (DCA)","title":"Data Conversation agent (DCA)","description":"What is DCA (Data Conversation Agent)?","permalink":"/datagol-knowlegde-base-v1/docs/AI Agents/data-conversation-agent"},{"id":"AI Agents/Data Science agent","title":"Data Science agent","description":"What is Data Science agent?","permalink":"/datagol-knowlegde-base-v1/docs/AI Agents/data-science-agent"},{"id":"AI Agents/Financial Deep Research agent","title":"Financial Deep Research agent","description":"The Financial Deep Research Agent is a powerful multi-agent architecture designed to perform in-depth, comprehensive financial analysis on any organization. It operates by delegating complex research tasks to a team of specialized, independent AI agents, ensuring a thorough and data-driven report.","permalink":"/datagol-knowlegde-base-v1/docs/AI Agents/financial-deep-research-agent"},{"id":"AI Agents/HubSpot agent","title":"HubSpot agent","description":"The HubSpot agent is an AI-powered tool designed to interact with your HubSpot CRM. It allows you to retrieve information and perform actions directly within your HubSpot environment by using natural language commands.","permalink":"/datagol-knowlegde-base-v1/docs/AI Agents/hubspot-agent"},{"id":"AI Agents/Jira agent","title":"Jira agent","description":"What is the Jira agent?","permalink":"/datagol-knowlegde-base-v1/docs/AI Agents/jira-agent"},{"id":"AI Agents/Knowledge Graph agent","title":"Knowledge Graph agent","description":"What is a Knowledge Graph agent?","permalink":"/datagol-knowlegde-base-v1/docs/AI Agents/knowledge-graph-agent"},{"id":"AI Agents/RAG agent","title":"RAG agent","description":"What is a RAG agent?","permalink":"/datagol-knowlegde-base-v1/docs/AI Agents/rag-agent"},{"id":"AI Agents/Salesforce agent","title":"Salesforce agent","description":"What is the Salesforce agent?","permalink":"/datagol-knowlegde-base-v1/docs/AI Agents/salesforce-agent"},{"id":"AI Agents/SQL agent","title":"SQL agent","description":"The DataGOL SQL Agent is an innovative tool designed to streamline SQL workflow by allowing users to interact with databases using natural language. This guide outlines how to use the agent\'s core features.","permalink":"/datagol-knowlegde-base-v1/docs/AI Agents/sql-agent"}],"unlisted":false}}')}}]);